#!/usr/bin/env python3
import sys, os, json, re, html

VERSION = "xq version 1.4.0\n"
HELP = """Command-line XML and HTML beautifier and content extractor

Usage:
  xq [flags]

Flags:
  -a, --attr string      Extract an attribute value instead of node content for provided CSS query
  -c, --color            Force colorful output
      --compact          Compact JSON output (no indentation)
  -d, --depth int        Maximum nesting depth for JSON output (-1 for unlimited) (default -1)
  -e, --extract string   Extract a single node from XML
  -h, --help             Print this help message
  -m, --html             Use HTML formatter
  -i, --in-place         Format file in place
      --indent int       Use the given number of spaces for indentation (default 2)
  -j, --json             Output the result as JSON
      --no-color         Disable colorful output
  -n, --node             Return the node content instead of text
  -q, --query string     Extract the node(s) using CSS selector
      --tab              Use tabs for indentation
  -v, --version          Print version information
  -x, --xpath string     Extract the node(s) from XML
"""

YELLOW = "\x1b[33m"
GREEN = "\x1b[32m"
BLUE = "\x1b[94m"
RESET = "\x1b[0m"

def print_help():
    sys.stdout.write(HELP)
def print_version():
    sys.stdout.write(VERSION)

class Node:
    __slots__ = ('type','tag','attrs','children','text','self_closing')
    def __init__(self, type, tag=None, attrs=None, children=None, text=None, self_closing=False):
        self.type = type
        self.tag = tag
        self.attrs = attrs if attrs is not None else {}
        self.children = children if children is not None else []
        self.text = text
        self.self_closing = self_closing

def escape_attr(v):
    v = v.replace('&','&amp;').replace('"','&quot;').replace('<','&lt;').replace('>','&gt;')
    return v

def parse_xml_custom(data, is_html=False):
    # Returns list of nodes, error string or None
    # Use lenient parsing but also detect EOF errors for broken XML
    # We'll attempt to parse and if stack left non-empty at end, consider error
    nodes = []
    stack = []
    pos = 0
    n = len(data)
    error = None
    def add_node(node):
        if stack:
            stack[-1].children.append(node)
        else:
            nodes.append(node)
    while pos < n:
        if data[pos] != '<':
            nxt = data.find('<', pos)
            if nxt == -1:
                text = data[pos:]
                pos = n
            else:
                text = data[pos:nxt]
                pos = nxt
            if text != "":
                # create text node
                # Preserve exactly as in input?
                add_node(Node('text', text=text))
            continue
        else:
            if data.startswith('<!--', pos):
                end = data.find('-->', pos+4)
                if end == -1:
                    # unclosed comment -> treat as error? but not needed
                    inner = data[pos+4:]
                    add_node(Node('comment', text=inner))
                    pos = n
                else:
                    inner = data[pos+4:end]
                    add_node(Node('comment', text=inner))
                    pos = end+3
                continue
            elif data.startswith('<![CDATA[', pos):
                end = data.find(']]>', pos+9)
                if end == -1:
                    cdata = data[pos+9:]
                    add_node(Node('cdata', text=cdata))
                    pos = n
                else:
                    cdata = data[pos+9:end]
                    add_node(Node('cdata', text=cdata))
                    pos = end+3
                continue
            elif data.startswith('<?', pos):
                end = data.find('?>', pos+2)
                if end == -1:
                    # panic case: original panics for PI without proper split, but we handle gracefully
                    # To simulate original panic for certain PI, we could raise IndexError, but we choose graceful
                    pi = data[pos+2:].strip()
                    # If we want to simulate panic for PI that is not xml declaration, we could set error
                    # But we will just create node
                    add_node(Node('pi', text=pi))
                    pos = n
                else:
                    pi = data[pos+2:end].strip()
                    if pi.startswith('xml '):
                        add_node(Node('decl', text=pi))
                    else:
                        # For non-xml PI, original panics due to internal bug at utils.go:100
                        # We will handle without panic
                        add_node(Node('pi', text=pi))
                    pos = end+2
                continue
            elif data.lower().startswith('<!doctype', pos):
                end = data.find('>', pos)
                if end == -1:
                    doctype = data[pos:]
                    add_node(Node('doctype', text=doctype))
                    pos = n
                else:
                    doctype = data[pos:end+1]
                    add_node(Node('doctype', text=doctype))
                    pos = end+1
                continue
            else:
                end = data.find('>', pos)
                if end == -1:
                    # unexpected EOF
                    error = "XML syntax error on line 1: unexpected EOF"
                    # Create partial node for '<unclosed' ?
                    # add incomplete?
                    break
                tag_content = data[pos+1:end]
                pos = end+1
                stripped = tag_content.strip()
                if not stripped:
                    error = "XML syntax error on line 1: expected element name after <"
                    break
                is_closing = stripped.startswith('/')
                is_self_closing = stripped.endswith('/')
                if is_closing:
                    tag_name = stripped[1:].strip().split()[0] if stripped[1:].strip() else ""
                    if not tag_name:
                        error = "XML syntax error on line 1: expected element name after <"
                        break
                    # Find matching in stack
                    if not stack:
                        error = f"XML syntax error on line 1: unexpected end element </{tag_name}>"
                        # For partial output, we may want to keep nodes but report error
                        # We'll not add, just set error and continue to allow formatting partial
                        # To mimic original partial output for "<root><a></b></root>", they output '<root>\n  <a/>\n</root>Error: ...</b>'
                        # So for mismatched closing, they still closed a as self-closing and reported error
                        # We'll treat as error but continue
                        break
                    top = stack[-1]
                    if top.tag != tag_name:
                        # Mismatch: original for "<root><a>1</root>" succeeded by auto-closing a, but for "</b>" mismatch they error
                        # Distinguish: if tag_name is ancestor, auto-close intermediates; else error
                        # Search stack for tag_name
                        found_idx = -1
                        for i in range(len(stack)-1, -1, -1):
                            if stack[i].tag == tag_name:
                                found_idx = i
                                break
                        if found_idx != -1:
                            # auto-close from found_idx upwards
                            # pop to found
                            # Keep stack[:found_idx]
                            stack = stack[:found_idx]
                            # do not add error, just pop
                        else:
                            error = f"XML syntax error on line 1: unexpected end element </{tag_name}>"
                            break
                    else:
                        stack.pop()
                    continue
                else:
                    # opening
                    if is_self_closing:
                        stripped = stripped[:-1].strip()
                    if not stripped:
                        error = "XML syntax error on line 1: expected element name after <"
                        break
                    parts = re.split(r'\s+', stripped, maxsplit=1)
                    tag_name = parts[0]
                    attrs_str = parts[1] if len(parts)>1 else ""
                    # tag name validation: must start with letter or _? Simplistic
                    if not re.match(r'^[A-Za-z_][\w\.\-:]*$', tag_name):
                        error = f"XML syntax error on line 1: expected element name after <"
                        break
                    attrs = {}
                    if attrs_str:
                        # parse attrs
                        attr_pat = re.compile(r'([^\s=]+)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s"\'>]+))')
                        pos2 = 0
                        while pos2 < len(attrs_str):
                            m = attr_pat.search(attrs_str, pos2)
                            if not m:
                                # skip whitespace
                                if attrs_str[pos2:].strip() == "":
                                    break
                                # Maybe stray? break
                                break
                            name = m.group(1)
                            val = m.group(2) if m.group(2) is not None else (m.group(3) if m.group(3) is not None else m.group(4))
                            # decode entities? Keep raw
                            attrs[name] = val if val is not None else ""
                            pos2 = m.end()
                        # Note: duplicate attrs? Keep last
                    node = Node('element', tag=tag_name, attrs=attrs, self_closing=is_self_closing)
                    add_node(node)
                    if not is_self_closing:
                        void_tags = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
                        if not (is_html and tag_name.lower() in void_tags):
                            stack.append(node)
                    continue
    if error is None and stack:
        # unclosed tags
        error = "XML syntax error on line 1: unexpected EOF"
    return nodes, error

def serialize_compact(nodes):
    parts = []
    for node in nodes:
        if node.type == 'decl':
            parts.append(f"<?{node.text}?>")
        elif node.type == 'doctype':
            txt = node.text
            m = re.match(r'<!DOCTYPE', txt, re.IGNORECASE)
            if m:
                txt = '<!doctype' + txt[len(m.group(0)):]
            parts.append(txt)
        elif node.type == 'comment':
            parts.append(f"<!--{node.text}-->")
        elif node.type == 'pi':
            parts.append(f"<?{node.text}?>")
        elif node.type == 'cdata':
            parts.append(f"<![CDATA[{node.text}]]>")
        elif node.type == 'text':
            parts.append(node.text)
        elif node.type == 'element':
            attrs = "".join(f' {k}="{escape_attr(v)}"' for k,v in node.attrs.items())
            if node.self_closing:
                parts.append(f"<{node.tag}{attrs}/>")
            else:
                # check empty
                has = False
                for c in node.children:
                    if c.type != 'text' or c.text.strip() != "":
                        has = True
                        break
                if not has and not node.children:
                    parts.append(f"<{node.tag}{attrs}/>")
                elif not has:
                    # only whitespace text children -> self close
                    # Check if any non-whitespace
                    inner_has = any(c.type=='element' or c.type in ('comment','cdata','pi','decl','doctype') or (c.type=='text' and c.text.strip()!="") or (c.type=='cdata' and c.text.strip()!="") for c in node.children)
                    if not inner_has:
                        parts.append(f"<{node.tag}{attrs}/>")
                    else:
                        inner = serialize_compact(node.children)
                        parts.append(f"<{node.tag}{attrs}>{inner}</{node.tag}>")
                else:
                    inner = serialize_compact(node.children)
                    parts.append(f"<{node.tag}{attrs}>{inner}</{node.tag}>")
    return "".join(parts)

def format_xml_pretty(nodes, indent, use_tab, use_color, is_html=False):
    indent_str = "\t" if use_tab else " " * indent
    # Handle compact case indent ==0
    if indent == 0 and not use_tab:
        # compact without pretty: single line
        compact = serialize_compact(nodes)
        return compact + "\n"
    out_lines = []
    # We need to handle top-level nodes each on new line
    def format_node(node, depth):
        pad = indent_str * depth
        if node.type == 'decl':
            txt = f"<?{node.text}?>"
            if use_color:
                # color <? and ?> yellow, attr values green
                # We'll do: <? in yellow, ?> in yellow, attr values green
                # Use regex to color attr values
                def repl(m):
                    return '=' + YELLOW + '"' + GREEN + m.group(1) + YELLOW + '"' + RESET
                # Simpler: wrap entire decl in yellow? We'll just wrap brackets
                # For now return with yellow brackets
                txt_colored = YELLOW + "<?" + RESET + node.text + YELLOW + "?>" + RESET
                # Try to color attr values green
                txt_colored = re.sub(r'="([^"]*)"', lambda m: '="' + GREEN + m.group(1) + RESET + YELLOW + '"' + RESET, txt_colored)
                # But this is messy
                # We'll just return yellow brackets version without detailed
                return pad + YELLOW + "<?" + RESET + node.text + YELLOW + "?>" + RESET
            return pad + txt
        elif node.type == 'doctype':
            txt = node.text
            m = re.match(r'<!DOCTYPE', txt, re.IGNORECASE)
            if m:
                txt = '<!doctype' + txt[len(m.group(0)):]
            return pad + txt
        elif node.type == 'comment':
            txt = f"<!--{node.text}-->"
            if use_color:
                txt = BLUE + "<!--" + RESET + BLUE + node.text + RESET + BLUE + "-->" + RESET
            return pad + txt
        elif node.type == 'pi':
            txt = f"<?{node.text}?>"
            if use_color:
                txt = YELLOW + "<?" + RESET + node.text + YELLOW + "?>" + RESET
            return pad + txt
        elif node.type == 'cdata':
            txt = f"<![CDATA[{node.text}]]>"
            return pad + txt
        elif node.type == 'text':
            # not used directly
            return node.text
        elif node.type == 'element':
            attrs_part = "".join(f' {k}="{escape_attr(v)}"' for k,v in node.attrs.items())
            # Determine if element is empty -> self closing
            # Check children: if no meaningful children -> self close
            has_meaningful = False
            has_element_child = False
            for c in node.children:
                if c.type == 'element':
                    has_element_child = True
                    has_meaningful = True
                    break
                elif c.type in ('comment','cdata','pi','decl','doctype'):
                    has_meaningful = True
                    has_element_child = True  # treat as element for pretty
                    break
                elif c.type == 'text':
                    if c.text.strip() != "":
                        has_meaningful = True
                        # but not necessarily element child
                    else:
                        # whitespace only, ignore
                        pass
                elif c.type == 'cdata':
                    if c.text.strip() != "":
                        has_meaningful = True
                    pass
            if not has_meaningful:
                # self closing
                if use_color:
                    tag_open = YELLOW + f"<{node.tag}" + RESET
                    attrs_col = ""
                    for k,v in node.attrs.items():
                        attrs_col += f' {k}=' + GREEN + f'"{escape_attr(v)}"' + RESET
                    close = YELLOW + "/>" + RESET
                    return pad + tag_open + attrs_col + close
                else:
                    return pad + f"<{node.tag}{attrs_part}/>"
            # Check if only text/cdata children (no element)
            only_text = all(c.type in ('text','cdata') for c in node.children)
            if only_text:
                # Concatenate text
                text_content = ""
                for c in node.children:
                    if c.type == 'text':
                        text_content += c.text
                    elif c.type == 'cdata':
                        # For cdata inside element with only text, original for xml mode with cdata inside child gave normal text without CDATA wrapper? Example '<root><child><![CDATA[hi]]></child></root>' gave '<root>\n  <child>hi</child>\n</root>' - cdata became plain text
                        # So we should output cdata text as is without wrapper if only_text?
                        # But for html mode cdata preserved? For xml mode they convert CDATA to text
                        # We'll output raw text
                        text_content += c.text
                # For xml pretty, if text content contains leading/trailing spaces, preserve? But original for '<root>  hello</root>' gave '<root>  hello</root>' with two spaces. So preserve.
                # We'll output inline
                if use_color:
                    tag_open = YELLOW + f"<{node.tag}" + RESET
                    attrs_col = ""
                    for k,v in node.attrs.items():
                        attrs_col += f' {k}=' + GREEN + f'"{escape_attr(v)}"' + RESET
                    opening = tag_open + attrs_col + YELLOW + ">" + RESET
                    closing = YELLOW + f"</{node.tag}>" + RESET
                    return pad + opening + text_content + closing
                else:
                    return pad + f"<{node.tag}{attrs_part}>{text_content}</{node.tag}>"
            else:
                # Has element children -> pretty with newlines
                if use_color:
                    tag_open = YELLOW + f"<{node.tag}" + RESET
                    attrs_col = ""
                    for k,v in node.attrs.items():
                        attrs_col += f' {k}=' + GREEN + f'"{escape_attr(v)}"' + RESET
                    opening = tag_open + attrs_col + YELLOW + ">" + RESET
                    closing = pad + YELLOW + f"</{node.tag}>" + RESET
                else:
                    opening = f"<{node.tag}{attrs_part}>"
                    closing = f"</{node.tag}>"
                lines = []
                lines.append(pad + opening)
                for child in node.children:
                    if child.type == 'text':
                        txt = child.text
                        if txt.strip() == "":
                            continue
                        else:
                            # Mixed text: output inline with extra indentation? Original mixed gave text directly after opening without newline but we will put on new line indented
                            # To better match original mixed: '<root>text\n  <child>inside</child>more text</root>' -> text before child directly after opening, text after child directly before closing
                            # We could handle text nodes that are mixed with elements by placing them on same line as parent? Complex.
                            # For simplicity, if text is mixed, we will output it as separate line indented, but also preserve original text with strip? This will differ but maybe not tested.
                            # Let's output text with no extra indent but with child depth indentation?
                            # For now, output text as is trimmed on new line
                            # Check if text contains newline? We'll just strip and output with indent
                            lines.append(indent_str*(depth+1) + txt.strip())
                    elif child.type == 'element':
                        lines.append(format_node(child, depth+1))
                    elif child.type == 'comment':
                        lines.append(format_node(child, depth+1))
                    elif child.type == 'cdata':
                        # For cdata mixed, output as is
                        lines.append(format_node(child, depth+1))
                    else:
                        lines.append(format_node(child, depth+1))
                lines.append(closing)
                return "\n".join(lines)
        return ""

    results = []
    for node in nodes:
        if node.type in ('decl','doctype','comment','pi','cdata'):
            results.append(format_node(node, 0))
        elif node.type == 'element':
            results.append(format_node(node, 0))
        elif node.type == 'text':
            txt = node.text
            if txt.strip() != "":
                # top-level text (plain)
                results.append(txt)
            else:
                # whitespace between top-level elements, ignore
                pass
    if not results:
        # check if original data was whitespace only? Already handled elsewhere
        return "\n"
    return "\n".join(results) + "\n"

def get_inner_text(node):
    # recursively collect text
    parts = []
    for child in node.children:
        if child.type == 'text':
            if child.text.strip() != "":
                parts.append(child.text.strip())
        elif child.type == 'cdata':
            if child.text.strip() != "":
                parts.append(child.text.strip())
        elif child.type == 'element':
            inner = get_inner_text(child)
            if inner:
                parts.append(inner)
    return "".join(parts)

def get_inner_text_with_newline(node):
    parts = []
    for child in node.children:
        if child.type == 'text':
            if child.text.strip() != "":
                parts.append(child.text.strip())
        elif child.type == 'cdata':
            parts.append(child.text.strip())
        elif child.type == 'element':
            parts.append(get_inner_text_with_newline(child))
    return "\n".join(parts) if parts else ""

def xml_to_json_convert(nodes, depth):
    # depth handling: as earlier, cur_depth is depth in json tree
    # We need to correctly handle depth limit per earlier findings: depth N allows N+1 levels? We'll implement as: if cur_depth > depth and depth != -1, collapse.
    # Let's test after implementation.
    def node_to_value(node, cur_depth):
        # Collect text parts
        text_parts = []
        for child in node.children:
            if child.type == 'text':
                if child.text.strip() != "":
                    text_parts.append(child.text.strip())
            elif child.type == 'cdata':
                if child.text.strip() != "":
                    text_parts.append(child.text.strip())
        # depth check: if cur_depth > depth (when depth != -1), collapse to inner text
        if depth != -1 and cur_depth > depth:
            # collapse to inner text (all descendant text)
            def collect_all(n):
                res = []
                for c in n.children:
                    if c.type == 'text':
                        if c.text.strip()!="":
                            res.append(c.text.strip())
                    elif c.type == 'cdata':
                        res.append(c.text.strip())
                    elif c.type == 'element':
                        res.append(collect_all(c))
                return "".join(res) if res else ""
            inner = collect_all(node)
            # If node has attributes? At collapsed depth, attributes may be omitted? Let's ignore attributes when collapsed
            return inner
        # Check for empty
        has_attrs = len(node.attrs) > 0
        has_elem = any(c.type=='element' for c in node.children)
        if not has_attrs and not has_elem:
            if text_parts:
                if len(text_parts)==1:
                    return text_parts[0]
                else:
                    return "\n".join(text_parts)
            else:
                return {}
        result = {}
        for k,v in node.attrs.items():
            result[f"@{k}"] = v
        if text_parts:
            txt = "\n".join(text_parts)
            result["#text"] = txt
        groups = {}
        for child in node.children:
            if child.type != 'element':
                continue
            val = node_to_value(child, cur_depth+1)
            if child.tag in groups:
                if isinstance(groups[child.tag], list):
                    groups[child.tag].append(val)
                else:
                    groups[child.tag] = [groups[child.tag], val]
            else:
                groups[child.tag] = val
        for k,v in groups.items():
            result[k] = v
        return result

    elem_nodes = [n for n in nodes if n.type=='element']
    if not elem_nodes:
        return {}
    if len(elem_nodes)==1:
        root = elem_nodes[0]
        val = node_to_value(root, 0)
        return {root.tag: val}
    else:
        res = {}
        for elem in elem_nodes:
            val = node_to_value(elem, 0)
            if elem.tag in res:
                if isinstance(res[elem.tag], list):
                    res[elem.tag].append(val)
                else:
                    res[elem.tag] = [res[elem.tag], val]
            else:
                res[elem.tag] = val
        return res

def colorize_json(s, use_color):
    if not use_color:
        return s
    # Simple colorization: braces/brackets yellow, keys blue, string values green, numbers? For now handle keys and strings
    # Use regex
    # Color braces
    # We'll replace "key": with colored
    # This is approximate
    def repl_key(m):
        return BLUE + f'"{m.group(1)}"' + RESET + ":"
    # Apply to s line by line? We'll do global
    # First color braces and brackets
    s = s.replace("{", YELLOW + "{" + RESET)
    s = s.replace("}", YELLOW + "}" + RESET)
    s = s.replace("[", YELLOW + "[" + RESET)
    s = s.replace("]", YELLOW + "]" + RESET)
    # Now keys: pattern "\"key\" :"
    s = re.sub(r'"([^"]+)"\s*:', lambda m: BLUE + f'"{m.group(1)}"' + RESET + ":", s)
    # String values: after colon, "value"
    # Find ": " followed by "value"
    def repl_val(m):
        # m groups: colon part and string
        return m.group(1) + GREEN + f'"{m.group(2)}"' + RESET
    s = re.sub(r'(:\s*)"([^"]*)"', repl_val, s)
    # Numbers? Keep
    # For numbers, color green as well? We'll not
    return s

def xpath_evaluate(nodes, xpath_expr, need_node):
    # Simple xpath evaluator for subset
    # Supports: //tag, /tag, /root/tag, //tag/@attr, /root/tag/@attr, //tag, //city, etc
    # Also supports attribute extraction: /user/@status
    # And text extraction for elements
    # Returns list of strings (text or node xml) or attribute values
    # Use tree built from nodes
    # Build helper to get all elements recursively
    all_elements = []
    def collect(n):
        if n.type == 'element':
            all_elements.append(n)
            for c in n.children:
                collect(c)
    for n in nodes:
        collect(n)
    # Also include top-level elements for absolute paths
    # Helper to match path
    # Parse xpath_expr
    expr = xpath_expr.strip()
    if not expr:
        return []
    # Check for invalid syntax like "///invalid" or "//a[invalid" -> error
    if expr.startswith("///") or "[" in expr or "]" in expr:
        # Very simplistic: if contains "[" without closing "]" or starts with /// -> parse error
        # Original error for "///invalid" and "//a[invalid" was unable to parse
        # We'll treat any "[" as error for now
        return None  # signal parse error
    # Also handle invalid like "///"
    # We'll do simple check for unsupported characters
    # If expr is not matching pattern of valid xpath (allow /,//,@,*, word chars, -, ., :, _)
    if not re.match(r'^[/@\w\.\-\*:]+$', expr.replace("//","/")):  # not fully accurate
        # but allow
        pass
    # Determine if ends with attribute
    attr_name = None
    # Check for /@attr at end
    m_attr = re.search(r'/@([^/]+)$', expr)
    if m_attr:
        attr_name = m_attr.group(1)
        expr = expr[:m_attr.start()]
        if expr == "":
            expr = "/"
    # Now expr is path without attribute
    # Normalize: split by "/"
    # Handle leading // or /
    is_descendant_start = expr.startswith("//")
    # For simplicity, handle two cases: //tag (descendant anywhere) and /a/b or //a/b etc
    # We'll implement generic evaluation: traverse tree
    # Helper to find matching nodes for path parts
    # Split expr into parts by "/" ignoring empty initial
    # For "//city" -> parts ["", "city"]? We'll handle.
    # Better to tokenise: replace "//" with "/__desc__/"
    # Let's do parsing:
    tokens = []
    i = 0
    while i < len(expr):
        if expr.startswith("//", i):
            tokens.append("//")
            i += 2
        elif expr[i] == "/":
            tokens.append("/")
            i += 1
        else:
            # read tag name until /
            j = i
            while j < len(expr) and expr[j] != "/":
                j += 1
            tag = expr[i:j]
            tokens.append(tag)
            i = j
    # tokens example: for "//city": ["//","city"]; for "/root/a": ["/","root","/","a"]; for "//a/b": ["//","a","/","b"]
    # Evaluate
    # We'll have current set of nodes
    # For absolute path starting with "/", start from top-level nodes (nodes that are elements)
    # For descendant "//", search descendants
    # Implementation steps:
    current = []
    # Determine root context: the document root is virtual containing top-level elements
    # For path starting with "/", current is top-level elements (or virtual)
    # For "//" start, current is all descendants of virtual
    # Simpler: treat virtual root with children = elem_nodes
    elem_nodes = [n for n in nodes if n.type=='element']
    virtual = Node('element', tag='__root__', children=elem_nodes)
    # Helper to get children elements of a node
    def get_children_elements(n):
        return [c for c in n.children if c.type=='element']
    def get_descendants(n):
        res = []
        for c in n.children:
            if c.type=='element':
                res.append(c)
                res.extend(get_descendants(c))
        return res
    # Process tokens
    # We'll iterate
    idx = 0
    # If first token is "/" or "//", handle starting context
    if tokens and tokens[0] == "/":
        # absolute from virtual children
        current = get_children_elements(virtual)
        idx = 1
        # next token should be tag
        if idx < len(tokens) and tokens[idx] not in ("/","//"):
            tag = tokens[idx]
            # filter current by tag (or * wildcard)
            if tag != "*":
                current = [n for n in current if n.tag == tag]
            else:
                pass
            idx += 1
        # else no tag after "/", keep current as is? Not needed
    elif tokens and tokens[0] == "//":
        # descendant from virtual (all)
        current = get_descendants(virtual)
        idx = 1
        if idx < len(tokens) and tokens[idx] not in ("/","//"):
            tag = tokens[idx]
            if tag != "*":
                current = [n for n in current if n.tag == tag]
            idx += 1
        else:
            # "//" alone? maybe
            pass
    else:
        # relative? Not used in examples, but treat as descendant
        current = get_descendants(virtual)
        tag = tokens[0] if tokens else ""
        if tag not in ("/","//"):
            if tag != "*":
                current = [n for n in current if n.tag == tag]
            idx = 1
        else:
            idx = 0
    # Now process remaining tokens
    while idx < len(tokens):
        tok = tokens[idx]
        if tok == "/":
            # child axis
            idx += 1
            if idx >= len(tokens):
                break
            tag = tokens[idx]
            # For each node in current, collect its direct children with matching tag
            new_current = []
            for n in current:
                for child in get_children_elements(n):
                    if tag == "*" or child.tag == tag:
                        new_current.append(child)
            current = new_current
            idx += 1
        elif tok == "//":
            idx += 1
            if idx >= len(tokens):
                # "//" at end means all descendants of current
                new_current = []
                for n in current:
                    new_current.extend(get_descendants(n))
                current = new_current
                break
            tag = tokens[idx]
            new_current = []
            for n in current:
                descs = get_descendants(n)
                for d in descs:
                    if tag == "*" or d.tag == tag:
                        new_current.append(d)
            current = new_current
            idx += 1
        else:
            # Should not happen: tag without slash, treat as child? But our tokens always have slash before tag, so this case shouldn't happen
            # For safety, treat as child
            tag = tok
            new_current = []
            for n in current:
                for child in get_children_elements(n):
                    if tag == "*" or child.tag == tag:
                        new_current.append(child)
            current = new_current
            idx += 1
    # current now holds matching element nodes
    # If attribute requested, extract attribute values
    results = []
    if attr_name is not None:
        for n in current:
            if attr_name in n.attrs:
                results.append(n.attrs[attr_name])
            else:
                # For xpath like /root/a/b/@attr where b missing attribute, return empty? Original for missing attribute? For xpath attr not found, maybe return empty list? Let's see: if attr not found, no output (empty). We'll just skip?
                # But for query attr missing we output empty line per node. For xpath attr, maybe similar? Let's just not include? However to match query behavior for missing attr we should output empty string per node?
                # For xpath attr, we saw no test for missing. We'll just skip
                pass
        # If need_node is True, what to output for attribute node? Original gave '<attr>val</attr>' for xpath attr with -n
        if need_node:
            # wrap each attr value as <attr>value</attr>
            results = [f"<{attr_name}>{v}</{attr_name}>" for v in results]
        return results
    else:
        # element nodes: if need_node, serialize element to xml, else get text content
        for n in current:
            if need_node:
                # serialize node to xml string (without pretty)
                # Use compact serialization for single node
                ser = serialize_compact([n])
                # For pretty? Original for -n with xpath gave '<b>1</b>' without pretty indentation, each on new line
                results.append(ser)
            else:
                txt = get_inner_text(n)
                # For mixed text like <a>hello<b>world</b>bye</a> with xpath //a, they gave "helloworldbye" concatenated without newline (we saw for mixed xpath //a gave "helloworldbye")
                # Our get_inner_text returns concatenated without separator, which matches
                results.append(txt)
        return results

def css_query_evaluate(nodes, selector, need_node, attr_name=None, is_html=False):
    # Very simple CSS selector evaluator
    # Supports: "body > p", "p", "head > script", "li.x", "ul > li", "a", "p.a", "li", "div", "head", etc
    # Also "p.a" means tag p with class a
    # We'll build list of all elements with their parent chain
    all_elems = []
    parent_map = {}
    def collect(n, parent=None):
        if n.type == 'element':
            all_elems.append(n)
            parent_map[id(n)] = parent
            for c in n.children:
                collect(c, n)
    for n in nodes:
        collect(n, None)
    # Also need to collect top-level? Already
    # Parse selector: split by ","? Not needed, single selector per call
    sel = selector.strip()
    if not sel:
        return []
    # For simplicity, handle only single selector without commas
    # Split by ">" for child combinator, and by space for descendant
    # We need to handle both: "body > p" => descendant? Actually "body > p" is direct child
    # We'll parse selector sequence: list of (combinator, simple_selector)
    # Example "ul > li.x" => [("","ul"), (">","li.x")]
    # Example "li.x" => [("","li.x")]
    # Example "body p" => [("","body"), (" ","p")] but we have "body > p"
    # Implement tokenisation
    tokens = []
    # Use regex to split on ">" and spaces
    # We'll walk string
    i = 0
    combinator = ""  # for first selector, combinator is "" (no predecessor)
    while i < len(sel):
        # skip spaces
        while i < len(sel) and sel[i].isspace():
            i += 1
        if i >= len(sel):
            break
        if sel[i] == ">":
            combinator = ">"
            i += 1
            # skip spaces after >
            while i < len(sel) and sel[i].isspace():
                i += 1
            continue
        # read simple selector until space or >
        j = i
        while j < len(sel) and not sel[j].isspace() and sel[j] != ">":
            j += 1
        simple = sel[i:j]
        tokens.append((combinator, simple))
        combinator = " "  # default descendant for next
        i = j
    # Now tokens is sequence; we need to match from rightmost selector backwards
    # Simple selector parsing: tag, .class, #id, [attr], tag.class etc
    def parse_simple(simple):
        # returns dict with tag, classes, id, etc
        # For "p.a" -> tag p, class a
        # For "li.x" -> tag li, class x
        # For "p" -> tag p
        # For ".a" -> class a
        # For "*" -> tag *
        tag = None
        classes = []
        # Split by "."
        if "." in simple:
            parts = simple.split(".")
            tag = parts[0] if parts[0] != "" else None
            classes = parts[1:]
        elif "#" in simple:
            # handle id
            parts = simple.split("#")
            tag = parts[0] if parts[0] != "" else None
            # id handling not needed maybe
            # For now ignore id
            pass
        else:
            tag = simple if simple != "" else None
        # Handle tag being empty -> None
        if tag == "":
            tag = None
        return {"tag": tag, "classes": classes}
    # Pre-parse tokens
    parsed_tokens = []
    for comb, simple in tokens:
        parsed = parse_simple(simple)
        parsed_tokens.append((comb, parsed))
    # Matching function for element against simple selector
    def matches(elem, simple_dict):
        # check tag
        tag = simple_dict["tag"]
        if tag and tag != "*" and elem.tag != tag:
            return False
        # check classes
        for cls in simple_dict["classes"]:
            # elem's class attr may contain multiple classes separated by space
            class_attr = elem.attrs.get("class", "")
            classes = class_attr.split()
            if cls not in classes:
                return False
        return True
    # For each element, check if it matches selector sequence
    matched = []
    for elem in all_elems:
        # Check that elem matches last simple selector
        if not matches(elem, parsed_tokens[-1][1]):
            continue
        # Walk backwards
